    h, w = len(grid), len(grid[0])
    # Locate solid rectangular frames by connected component and bounding box.
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == color and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        todo.append((yy, xx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            if (all(grid[r0][x] == color and grid[r1][x] == color
                    for x in range(c0, c1+1)) and
                all(grid[y][c0] == color and grid[y][c1] == color
                    for y in range(r0, r1+1))):
                frames.append((r0, r1, c0, c1, color))

    # The one already-patterned frame is the mask/template.
    template = None
    for frame in frames:
        r0, r1, c0, c1, color = frame
        mask = [[grid[y][x] != 0 for x in range(c0+1, c1)]
                for y in range(r0+1, r1)]
        if any(any(row) for row in mask):
            template = (frame, mask)
            break
    if template is None:
        return [row[:] for row in grid]

    source, mask = template
    sh, sw = len(mask), len(mask[0])
    out = [[0] * w for _ in range(h)]
    # Keep the source frame and its original interior intact.
    r0, r1, c0, c1, _ = source
    for y in range(r0, r1+1):
        for x in range(c0, c1+1):
            out[y][x] = grid[y][x]
    # Recreate only frames with matching cavity dimensions; discard other shapes.
    for frame in frames:
        if frame == source:
            continue
        r0, r1, c0, c1, color = frame
        ih, iw = r1-r0-1, c1-c0-1
        if (ih, iw) != (sh, sw):
            continue
        for x in range(c0, c1+1):
            out[r0][x] = color
            out[r1][x] = color
        for y in range(r0, r1+1):
            out[y][c0] = color
            out[y][c1] = color
        for i in range(sh):
            for j in range(sw):
                if mask[i][j]:
                    out[r0+1+i][c0+1+j] = color
    return out
